import { normalizeCheckinDraft,validateCheckinDraft,normalizeHabitDefinitionDraft,validateHabitDefinitionDraft } from './activity-drafts.js';
function setStatus(root,scope,message,kind='info'){const node=root.querySelector?.(`[data-engagement-status="${scope}"]`);if(!node)return;node.textContent=message;node.dataset.status=kind;}
function formValues(form){const data=new FormData(form);return Object.fromEntries(data.entries());}
function dispatchError(root,action,error){if(typeof CustomEvent==='function')root.dispatchEvent(new CustomEvent('m26:engagement-error',{bubbles:true,detail:{action,code:error.message}}));}
export function createEngagementController({root,store,draftRepository,service,submitCheckin,savePrivateNote}={}){
  if(!root?.addEventListener||!store?.getState||!draftRepository?.save)throw new Error('M26_ENGAGEMENT_CONTROLLER_REQUIRED');let mounted=false;
  function context(){const state=store.getState();const role=String(state.identity?.role||'');const clientId=role==='client'||role==='cliente'?state.identity?.clientId:state.selectedClientId;return {state,role,clientId};}
  async function saveCheckinDraft(){const form=root.querySelector?.('[data-engagement-form="checkin"]');if(!form)throw new Error('M26_CHECKIN_FORM_REQUIRED');const {clientId}=context();if(!clientId)throw new Error('M26_CLIENT_CONTEXT_REQUIRED');const value=normalizeCheckinDraft(formValues(form));await draftRepository.save(clientId,'checkin',value);setStatus(root,'checkin','Borrador guardado en este dispositivo. Aún no está confirmado.','pending');return value;}
  async function submit(){const form=root.querySelector?.('[data-engagement-form="checkin"]');if(!form)throw new Error('M26_CHECKIN_FORM_REQUIRED');const {clientId,role}=context();const validation=validateCheckinDraft(formValues(form));if(!validation.ok)throw new Error(`M26_CHECKIN_INVALID:${validation.errors.join(',')}`);await draftRepository.save(clientId,'checkin',validation.value);const result=service?.registerCheckin?await service.registerCheckin({clientId,checkin:validation.value}):typeof submitCheckin==='function'?await submitCheckin({clientId,role,checkin:validation.value}):(()=>{throw new Error('M26_CHECKIN_BACKEND_CAPABILITY_REQUIRED');})();if(result?.ok){await draftRepository.remove(clientId,'checkin');setStatus(root,'checkin','Check-in confirmado por el servidor.','success');}else setStatus(root,'checkin',result?.queued?'Check-in guardado para sincronizar al recuperar conexión.':'El check-in permanece como borrador pendiente.','pending');return result;}
  async function saveHabitDraft(){const form=root.querySelector?.('[data-engagement-form="habit-definition"]');if(!form)throw new Error('M26_HABIT_FORM_REQUIRED');const {clientId}=context();const value=normalizeHabitDefinitionDraft(formValues(form));await draftRepository.save(clientId,'habit-definition',value);setStatus(root,'habit','Borrador de hábito guardado localmente.','pending');return value;}
  async function defineHabit(){const form=root.querySelector?.('[data-engagement-form="habit-definition"]');if(!form)throw new Error('M26_HABIT_FORM_REQUIRED');const {clientId}=context();const validation=validateHabitDefinitionDraft(formValues(form));if(!validation.ok)throw new Error(`M26_HABIT_INVALID:${validation.errors.join(',')}`);await draftRepository.save(clientId,'habit-definition',validation.value);if(!service?.defineHabit)throw new Error('M26_HABIT_BACKEND_CAPABILITY_REQUIRED');const result=await service.defineHabit({clientId,habit:validation.value});if(result?.ok){await draftRepository.remove(clientId,'habit-definition');form.reset?.();setStatus(root,'habit','Hábito confirmado por el servidor.','success');}else setStatus(root,'habit','El hábito permanece pendiente y no se muestra como confirmado.','pending');return result;}
  async function logHabit(button){const {clientId}=context();const habitId=button.getAttribute('data-habit-id');if(!habitId)throw new Error('M26_HABIT_ID_REQUIRED');if(!service?.registerHabit)throw new Error('M26_HABIT_BACKEND_CAPABILITY_REQUIRED');const completed=button.getAttribute('data-completed')!=='false';const result=await service.registerHabit({clientId,log:{habitId,completed,recordedAt:new Date().toISOString()}});setStatus(root,'habit-log',result?.ok?'Hábito registrado.':result?.queued?'Registro guardado para sincronización.':'Registro pendiente. ',result?.ok?'success':'pending');return result;}
  async function privateNote(){const {clientId,role}=context();if(!['admin','coach'].includes(role))throw new Error('M26_PRIVATE_NOTE_ROLE_FORBIDDEN');const field=root.querySelector?.('[data-private-note-draft]');const value=String(field?.value||'').trim();if(value.length<3)throw new Error('M26_PRIVATE_NOTE_REQUIRED');const result=service?.createPrivateNote?await service.createPrivateNote({clientId,body:value}):typeof savePrivateNote==='function'?await savePrivateNote({clientId,body:value}):(()=>{throw new Error('M26_PRIVATE_NOTE_BACKEND_CAPABILITY_REQUIRED');})();if(result?.ok){field.value='';setStatus(root,'private-note','Nota privada confirmada.','success');}else setStatus(root,'private-note','La nota no fue confirmada.','pending');return result;}
  async function onClick(event){const button=event.target.closest?.('[data-engagement-action]');if(!button)return;const action=button.getAttribute('data-engagement-action');button.disabled=true;button.setAttribute('aria-busy','true');try{if(action==='save-checkin-draft')await saveCheckinDraft();else if(action==='submit-checkin')await submit();else if(action==='save-habit-draft')await saveHabitDraft();else if(action==='define-habit')await defineHabit();else if(action==='log-habit')await logHabit(button);else if(action==='save-private-note')await privateNote();}catch(error){const scope=action.includes('private-note')?'private-note':action.includes('habit')?'habit':'checkin';setStatus(root,scope,error.message,'error');dispatchError(root,action,error);}finally{button.disabled=false;button.removeAttribute('aria-busy');}}
  async function restoreScope(scope,formSelector){const {clientId}=context();if(!clientId)return;const record=await draftRepository.load(clientId,scope);const form=root.querySelector?.(formSelector);if(!record?.value||!form)return;for(const [key,value] of Object.entries(record.value)){const field=form.elements?.namedItem?.(key);if(field&&value!==null&&value!==undefined)field.value=String(value);}setStatus(root,scope==='checkin'?'checkin':'habit','Borrador local recuperado. Aún no está confirmado.','pending');}
  async function restore(){await restoreScope('checkin','[data-engagement-form="checkin"]');await restoreScope('habit-definition','[data-engagement-form="habit-definition"]');}
  return Object.freeze({mount(){if(mounted)return;root.addEventListener('click',onClick);mounted=true;void restore();},destroy(){if(!mounted)return;root.removeEventListener('click',onClick);mounted=false;},restore,saveCheckinDraft,saveHabitDraft});
}
